window.ACTIVIDAD = {"id": "ut2-05-tree-test", "titulo": "Tree test", "subtitulo": "UT2 · Diseño y desarrollo web · 3º EAS Diseño Gráfico", "etiqueta": "UT2 · Diseño y desarrollo web", "objetivo": "Haz de usuario en un tree test: busca cosas en el menú de una tienda de bicis inventada y descubre qué mide esta prueba de navegación.", "minutos": 25, "preguntasPorIntento": 10, "aprobado": 50, "garantizar": ["arbol", "arbol", "arbol", "arbol", "arbol", "arbol", "arbol", "arbol", "unica", "vf"], "arboles": {"pedalea": {"nombre": "Pedalea · tienda y taller de bicis", "nodos": [{"id": "a", "texto": "Bicis", "hijos": [{"id": "a1", "texto": "Carretera"}, {"id": "a2", "texto": "Montaña"}, {"id": "a3", "texto": "Ciudad y plegables"}, {"id": "a4", "texto": "Eléctricas"}, {"id": "a5", "texto": "Infantiles"}]}, {"id": "b", "texto": "Equipamiento", "hijos": [{"id": "b1", "texto": "Cascos"}, {"id": "b2", "texto": "Ropa y calzado"}, {"id": "b3", "texto": "Luces y candados"}, {"id": "b4", "texto": "Recambios"}]}, {"id": "c", "texto": "Taller", "hijos": [{"id": "c1", "texto": "Reparaciones", "hijos": [{"id": "c11", "texto": "Pedir cita"}, {"id": "c12", "texto": "Precios del taller"}]}, {"id": "c2", "texto": "Revisión anual"}, {"id": "c3", "texto": "Cursos de mecánica"}]}, {"id": "d", "texto": "Alquiler", "hijos": [{"id": "d1", "texto": "Rutas guiadas"}, {"id": "d2", "texto": "Alquiler por días"}, {"id": "d3", "texto": "Empresas y grupos"}]}, {"id": "e", "texto": "Mi cuenta", "hijos": [{"id": "e1", "texto": "Mis pedidos", "hijos": [{"id": "e11", "texto": "Seguimiento del envío"}, {"id": "e12", "texto": "Facturas"}]}, {"id": "e2", "texto": "Mis datos", "hijos": [{"id": "e21", "texto": "Direcciones"}, {"id": "e22", "texto": "Contraseña"}]}, {"id": "e3", "texto": "Mis citas del taller"}]}, {"id": "f", "texto": "Ayuda", "hijos": [{"id": "f1", "texto": "Envíos y entregas"}, {"id": "f2", "texto": "Cambios y devoluciones"}, {"id": "f3", "texto": "Garantías"}, {"id": "f4", "texto": "Formas de pago"}, {"id": "f5", "texto": "Contacto"}]}, {"id": "g", "texto": "Sobre Pedalea", "hijos": [{"id": "g1", "texto": "La tienda: horario y cómo llegar"}, {"id": "g2", "texto": "Trabaja con nosotros"}, {"id": "g3", "texto": "Aviso legal y privacidad"}]}]}}, "diapositivas": {"17": "Actividades de un diseñador UX: investigaciones (test con usuarios, card sorting, tree test, five second test, personas, focus group), evaluaciones (análisis heurísticos), análisis de datos (test A/B), arquitectura de información y wireframes.", "83": "Una buena arquitectura de la información busca organizar el contenido de forma clara y lógica, según el modelo mental de los usuarios, para facilitar al máximo el acceso a ella.", "94": "Etiquetado. Qué hacemos: definir la terminología que utilizará el sistema. Cómo: eligiendo las palabras para títulos, encabezados, nombres de secciones, palabras clave, productos y transacciones. La buena voluntad no basta: hay que hacer un test UX a los usuarios para conocer cómo lo llamarían, cómo lo buscarían y si entienden la terminología.", "96": "Ejemplo de etiquetado: la sección de devoluciones se llama distinto en cada empresa. Zara: Cambios y devoluciones. Mango: Devoluciones, cambios y reembolsos. El Corte Inglés: Devolución y reembolso. MediaMarkt: Devoluciones. PcComponentes: Devoluciones y garantías. Mercadona: Quiero devolver / cambiar un producto. pcacierto.com: Devoluciones y reclamaciones.", "102": "Estructura jerárquica: navegación en forma de árbol; se organiza de lo general a lo concreto. Es de las más populares. Diagrama de una caja arriba con tres ramas y un nivel más debajo.", "103": "Estructura jerárquica. Ventaja: el usuario puede hacerse un mapa mental del sitio y saber dónde está, qué categoría está viendo y cómo ha llegado. Inconveniente: para ir a otro sitio debe volver sobre sus pasos o comenzar de nuevo y tomar decisiones diferentes; no se permite la libre navegación.", "121": "¿Cómo comprobamos la usabilidad web (de la web, de un componente, de una página)? Con un análisis heurístico y, al menos, comprobando que los usuarios pueden contestar: ¿Dónde estoy? ¿Cómo llegué aquí? ¿A dónde puedo ir después? ¿Qué puedo hacer en este momento? ¿Cómo puedo regresar al punto anterior?", "142": "El sistema de navegación se compone de: 4º, menú terciario o en pie de página, que da acceso a información secundaria para el usuario o que la web está obligada a mostrar. Ejemplo: pie de página de elDiario.es con Aviso legal, Política de privacidad, FAQ, Mis cookies y Contacto."}, "banco": [{"id": "t01", "tipo": "arbol", "grupo": "devolver", "arbol": "pedalea", "enunciado": "Te ha llegado un casco que te queda pequeño. No lo quieres y quieres que te den el dinero. ¿Dónde lo buscarías?", "destinos": ["f2", "e1"], "ramas": ["f", "e1"], "explicacion": "Lo esperado es «Ayuda › Cambios y devoluciones». También vale «Mi cuenta › Mis pedidos», porque muchas tiendas dejan devolver desde el pedido. Fíjate en que la tarea no dice «devolución»: en un tree test las tareas no repiten las palabras del menú, para comprobar si la etiqueta se entiende. Cada tienda llama distinto a esta sección.", "diapositiva": 96}, {"id": "t16", "tipo": "arbol", "grupo": "devolver", "arbol": "pedalea", "enunciado": "Pediste un candado y te ha llegado otro modelo. Quieres que te manden el que pediste. ¿Dónde lo buscarías?", "destinos": ["f2", "e1"], "ramas": ["f", "e1"], "explicacion": "Lo esperado es «Ayuda › Cambios y devoluciones»; también vale «Mi cuenta › Mis pedidos». No es «Equipamiento › Luces y candados»: ahí se compra, no se cambia un pedido. La etiqueta debe usar las palabras que el usuario buscaría; por eso cada tienda la prueba con sus usuarios.", "diapositiva": 96}, {"id": "t02", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Compraste unas luces hace tres días. Quieres saber por dónde va tu paquete. ¿Dónde lo buscarías?", "destinos": ["e11"], "ramas": ["e1", "f1"], "explicacion": "Está en «Mi cuenta › Mis pedidos › Seguimiento del envío»: es información de tu pedido, no general. «Ayuda › Envíos y entregas» explica plazos para todos, pero no dónde está tu paquete; por eso suma la mitad. Una estructura jerárquica va de lo general a lo concreto.", "diapositiva": 102}, {"id": "t03", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Tu bici hace un ruido raro al frenar. Quieres llevarla al taller el jueves. ¿Dónde lo buscarías?", "destinos": ["c11"], "ramas": ["c", "e3"], "explicacion": "Está en «Taller › Reparaciones › Pedir cita». «Mi cuenta › Mis citas del taller» muestra las citas que ya tienes, no deja pedir una nueva; suma la mitad porque estás cerca. Si dudaste entre las dos, la etiqueta no responde bien a «¿qué puedo hacer en este momento?».", "diapositiva": 121}, {"id": "t04", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Antes de ir al taller, quieres saber cuánto te cobrarán por arreglar un pinchazo. ¿Dónde lo buscarías?", "destinos": ["c12"], "explicacion": "Está en «Taller › Reparaciones › Precios del taller». Es un tercer nivel: hay que bajar de lo general (Taller) a lo concreto (Reparaciones y después Precios). Así se organiza una estructura jerárquica.", "diapositiva": 102}, {"id": "t05", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Tu hija de 7 años necesita su primera bici. ¿Dónde la buscarías?", "destinos": ["a5"], "explicacion": "Está en «Bicis › Infantiles». Las bicis se agrupan por el uso o por quién las usa (carretera, montaña, ciudad, infantiles…). Una buena organización sigue el modelo mental del usuario: piensa en «una bici para mi hija», no en tallas o marcas.", "diapositiva": 83}, {"id": "t06", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Necesitas la factura de tu última compra para pasarla a tu empresa. ¿Dónde la buscarías?", "destinos": ["e12"], "ramas": ["e1"], "explicacion": "Está en «Mi cuenta › Mis pedidos › Facturas». La factura es de un pedido tuyo, así que va dentro de tu cuenta y de tus pedidos. «Ayuda › Formas de pago» explica cómo pagar, pero no guarda tus facturas.", "diapositiva": 102}, {"id": "t07", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Quieres aprender a ajustar tú misma los cambios de tu bici. ¿Dónde lo buscarías?", "destinos": ["c3"], "explicacion": "Está en «Taller › Cursos de mecánica». No es una reparación (no la arregla el taller por ti) ni un producto. Si muchas personas lo buscan en «Ayuda», quizá la etiqueta o el lugar no siguen su modelo mental.", "diapositiva": 83}, {"id": "t08", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Unos amigos vienen de fuera el sábado. Queréis recorrer la ciudad en bici con alguien que os la enseñe. ¿Dónde lo buscarías?", "destinos": ["d1"], "explicacion": "Está en «Alquiler › Rutas guiadas». Las bicis del menú «Bicis» son para comprar. Aquí buscas un servicio con guía. Una etiqueta clara evita que el usuario tenga que imaginar qué hay detrás de cada palabra.", "diapositiva": 94}, {"id": "t09", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Te has mudado. Quieres que tus próximos pedidos lleguen a tu casa nueva. ¿Dónde lo buscarías?", "destinos": ["e21"], "ramas": ["e2"], "explicacion": "Está en «Mi cuenta › Mis datos › Direcciones». Es un dato tuyo que se guarda en tu cuenta. «Ayuda › Envíos y entregas» habla de los envíos en general, no cambia tus datos.", "diapositiva": 102}, {"id": "t10", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Quieres comprar una bici eléctrica, pero solo si puedes pagarla en varios meses. ¿Dónde lo buscarías?", "destinos": ["f4"], "explicacion": "Está en «Ayuda › Formas de pago». No está en «Bicis › Eléctricas»: el pago a plazos vale para cualquier compra. Agrupar la información común en un sitio evita repetirla en cada sección.", "diapositiva": 83}, {"id": "t11", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Tu bici eléctrica tiene dos meses y ha dejado de cargar. Crees que no deberías pagar por arreglarla. ¿Dónde lo buscarías?", "destinos": ["f3"], "ramas": ["f", "c1"], "explicacion": "Está en «Ayuda › Garantías»: una avería en un producto nuevo la cubre la garantía. «Taller › Reparaciones» es para arreglos que pagas tú; por eso suma la mitad. Algunas tiendas juntan «Devoluciones y garantías» en una sola etiqueta: el etiquetado se decide con los usuarios.", "diapositiva": 96}, {"id": "t12", "tipo": "arbol", "arbol": "pedalea", "enunciado": "El domingo quieres ir a la tienda física, pero no sabes si abre. ¿Dónde lo buscarías?", "destinos": ["g1", "f5"], "ramas": ["g", "f"], "explicacion": "Lo esperado es «Sobre Pedalea › La tienda: horario y cómo llegar». También vale «Ayuda › Contacto», porque muchas webs ponen ahí la dirección y el horario. Esta información secundaria suele ir también en el pie de página (menú terciario).", "diapositiva": 142}, {"id": "t13", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Has visto que buscan a alguien para la tienda. Quieres enviar tu currículum. ¿Dónde lo buscarías?", "destinos": ["g2"], "explicacion": "Está en «Sobre Pedalea › Trabaja con nosotros». Es información secundaria para quien compra: por eso no ocupa un lugar en el menú principal, que lleva a los sitios más relevantes, y suele ir en el pie de página (menú terciario).", "diapositiva": 142}, {"id": "t14", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Te preocupa a quién puede pasar la tienda tu correo y tu teléfono. ¿Dónde lo buscarías?", "destinos": ["g3"], "explicacion": "Está en «Sobre Pedalea › Aviso legal y privacidad». «Mi cuenta › Mis datos» sirve para cambiar tus datos, no explica qué hace la tienda con ellos. Es información que la web está obligada a mostrar: va en el menú terciario o pie de página.", "diapositiva": 142}, {"id": "t15", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Tu empresa quiere 12 bicis para una jornada de equipo en el campo. ¿Dónde lo buscarías?", "destinos": ["d3"], "explicacion": "Está en «Alquiler › Empresas y grupos». «Alquiler por días» es para particulares y pocas bicis. Las etiquetas deben ayudar a cada tipo de usuario a reconocerse: así no tiene que imaginar dónde está lo suyo.", "diapositiva": 94}, {"id": "t17", "tipo": "arbol", "arbol": "pedalea", "enunciado": "Pinchas a menudo. Quieres comprar cámaras para cambiarlas tú en casa. ¿Dónde las buscarías?", "destinos": ["b4"], "explicacion": "Está en «Equipamiento › Recambios». Compras piezas, no un servicio del taller. Si muchas personas fueran a «Taller», el tree test diría que la etiqueta «Recambios» no se entiende o que falta un enlace desde el taller.", "diapositiva": 94}, {"id": "s01", "tipo": "unica", "enunciado": "¿Qué comprueba un tree test como el que acabas de hacer?", "opciones": [{"id": "a", "texto": "Si los usuarios encuentran cada cosa usando solo los nombres y la estructura del menú.", "correcta": true}, {"id": "b", "texto": "Si los usuarios agrupan las tarjetas de contenido en los mismos grupos que el equipo."}, {"id": "c", "texto": "Qué recuerdan los usuarios de un diseño que han visto solo cinco segundos."}, {"id": "d", "texto": "Cuál de dos versiones publicadas de la web consigue más ventas."}], "explicacion": "En el tree test el usuario recibe tareas y busca en un menú solo de texto, sin colores ni imágenes. Así se ve si la estructura y las etiquetas le llevan a donde espera. Agrupar tarjetas es el card sorting; ver un diseño cinco segundos es el five second test; comparar dos versiones publicadas es el test A/B. Todas son investigaciones de la diseñadora UX.", "diapositiva": 17}, {"id": "s02", "tipo": "unica", "enunciado": "En un tree test, 7 de cada 10 personas buscan «cambiar la dirección de envío» en «Ayuda» y no en «Mi cuenta». ¿Qué decides?", "opciones": [{"id": "a", "texto": "Revisar dónde está o cómo se llama, porque el menú debe seguir su modelo mental.", "correcta": true}, {"id": "b", "texto": "Dejarlo igual: las personas aprenderán dónde está con el uso."}, {"id": "c", "texto": "Poner «Mi cuenta» en un color más llamativo."}, {"id": "d", "texto": "Repetir la prueba con otras personas hasta que acierten."}], "explicacion": "La arquitectura de la información organiza el contenido según el modelo mental de los usuarios. Si la mayoría lo busca en otro sitio, hay que cambiar la estructura o la etiqueta (o enlazarlo desde los dos sitios). Si hay que aprender a navegar, la web debe mejorar. Un color más llamativo no arregla una estructura que no se entiende.", "diapositiva": 83}, {"id": "s03", "tipo": "unica", "enunciado": "En el tree test, la línea «Inicio › Ayuda › Garantías» (migas de pan) te ayuda sobre todo a responder…", "opciones": [{"id": "a", "texto": "¿Dónde estoy? y ¿cómo llegué aquí?", "correcta": true}, {"id": "b", "texto": "¿Qué puedo hacer en este momento? y ¿a dónde puedo ir después?"}, {"id": "c", "texto": "¿Es fiable esta tienda? y ¿cuánto cuesta el envío?"}, {"id": "d", "texto": "¿Qué colores usa la marca? y ¿qué tipografía?"}], "explicacion": "Las migas de pan muestran tu posición en el árbol y el camino desde Inicio: responden a «¿dónde estoy?» y «¿cómo llegué aquí?». «¿A dónde puedo ir después?» lo responde la lista de apartados, y «¿qué puedo hacer?», botones como «Lo buscaría aquí».", "diapositiva": 121}, {"id": "s04", "tipo": "unica", "enunciado": "En la web de Pedalea, ¿dónde suele ir el enlace «Aviso legal y privacidad»?", "opciones": [{"id": "a", "texto": "En el menú terciario o pie de página.", "correcta": true}, {"id": "b", "texto": "En el menú principal, junto a «Bicis» y «Taller»."}, {"id": "c", "texto": "Solo en el buscador, porque casi nadie lo consulta."}, {"id": "d", "texto": "Dentro de la ficha de cada bici."}], "explicacion": "El menú terciario o pie de página da acceso a información secundaria o que la web está obligada a mostrar, como el aviso legal y la privacidad. El menú principal lleva a los lugares más relevantes del sitio (y a la búsqueda).", "diapositiva": 142}, {"id": "s05", "tipo": "vf", "enunciado": "Un tree test se puede hacer antes de diseñar la interfaz: basta con los nombres del menú ordenados en árbol.", "correcta": true, "explicacion": "Verdadero. Como en esta actividad, el menú es solo texto: no hacen falta colores, imágenes ni maquetación. Por eso sirve para comprobar la estructura y el etiquetado al principio, cuando cambiarlos aún cuesta poco.", "diapositiva": 94}, {"id": "s06", "tipo": "vf", "enunciado": "Si en un tree test casi nadie encuentra «Garantías», la solución es poner ese apartado con letra más grande.", "correcta": false, "explicacion": "Falso. En un tree test no hay diseño visual: si no lo encuentran, el problema está en la estructura (dónde está) o en el etiquetado (cómo se llama), no en el tamaño de la letra. Hay que cambiar el lugar o la palabra y volver a probar con usuarios.", "diapositiva": 94}, {"id": "s07", "tipo": "vf", "enunciado": "En una estructura jerárquica, para ir a otra rama tienes que volver sobre tus pasos o empezar de nuevo.", "correcta": true, "explicacion": "Verdadero. Es el inconveniente de la estructura jerárquica (en árbol): no permite la libre navegación. Lo has vivido en el tree test con «Volver» y las migas. Su ventaja es que el usuario se hace un mapa mental y sabe dónde está y cómo ha llegado.", "diapositiva": 103}]};
